#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
$pathsep=":"
$env_node_path=$env:NODE_PATH
$new_node_path="C:\Users\Zain-pc\Documents\berry-bloom\node_modules\.pnpm\nitropack@2.13.4_rolldown@1_cdbb52c97eefb363a0766aa82b3b5f22\node_modules\nitropack\node_modules;C:\Users\Zain-pc\Documents\berry-bloom\node_modules\.pnpm\nitropack@2.13.4_rolldown@1_cdbb52c97eefb363a0766aa82b3b5f22\node_modules;C:\Users\Zain-pc\Documents\berry-bloom\node_modules\.pnpm\node_modules"
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
  # are installed in the same directory
  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/mnt/c/Users/Zain-pc/Documents/berry-bloom/node_modules/.pnpm/nitropack@2.13.4_rolldown@1_cdbb52c97eefb363a0766aa82b3b5f22/node_modules/nitropack/node_modules:/mnt/c/Users/Zain-pc/Documents/berry-bloom/node_modules/.pnpm/nitropack@2.13.4_rolldown@1_cdbb52c97eefb363a0766aa82b3b5f22/node_modules:/mnt/c/Users/Zain-pc/Documents/berry-bloom/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
  $env:NODE_PATH="$new_node_path$pathsep$env_node_path"
}

$ret=0
if (Test-Path "$basedir/node$exe") {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../../dist/cli/index.mjs" $args
  } else {
    & "$basedir/node$exe"  "$basedir/../../dist/cli/index.mjs" $args
  }
  $ret=$LASTEXITCODE
} else {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe"  "$basedir/../../dist/cli/index.mjs" $args
  } else {
    & "node$exe"  "$basedir/../../dist/cli/index.mjs" $args
  }
  $ret=$LASTEXITCODE
}
$env:NODE_PATH=$env_node_path
exit $ret
